#include "/REQUIRED_EXTERNAL_INPUT/Corsairs/experiments/native-metal/ship_laser_geometry.hpp"
#include <cstdio>
#include <cassert>
using namespace storm_ship_laser;
Vertex vertex(Vec3 p){Vertex v;v.position=p;return v;}
Mesh box(float radius=1,bool reverse=false){Mesh m;Vec3 p[8]={{-radius,-radius,-radius},{radius,-radius,-radius},{radius,radius,-radius},{-radius,radius,-radius},{-radius,-radius,radius},{radius,-radius,radius},{radius,radius,radius},{-radius,radius,radius}};int f[6][4]={{0,3,2,1},{4,5,6,7},{0,4,7,3},{1,2,6,5},{0,1,5,4},{3,7,6,2}};for(auto&q:f)for(auto ids:{std::array<int,3>{q[0],q[1],q[2]},std::array<int,3>{q[0],q[2],q[3]}}){Triangle t={vertex(p[ids[0]]),vertex(p[ids[1]]),vertex(p[ids[2]])};if(reverse)std::swap(t[1],t[2]);for(auto&v:t)v.normal=storm_ship_hull::normalized(storm_ship_hull::cross(t[1].position-t[0].position,t[2].position-t[0].position));m[0].push_back(t);}return m;}
Plane bore(float x=0,float y=0){Plane p{{0,0,-1},0};BeamSample b;b.start={x,y,1.01f};b.direction={0,0,-1};b.radius=.13f;b.depth=.4f;p.beams={b};return p;}
double volume(const Mesh&m){double v=0;for(const auto&o:m)for(const auto&t:o.second)v+=double(storm_ship_hull::dot(t[0].position,storm_ship_hull::cross(t[1].position,t[2].position)))/6;return v;}
void report(const char*name,const Mesh&m){size_t faces=0;double a=0;for(const auto&o:m)for(const auto&t:o.second){++faces;a+=storm_ship_hull::area(t);}printf("%s closed=%.12f signed=%.12f area=%.12f faces=%zu\n",name,closedCutVolume(m),volume(m),a,faces);}
void edges(const Mesh&m){std::map<PositionEdge,std::pair<int,int>>all;for(const auto&o:m)for(const auto&t:o.second){if(!topologyTriangle(t))continue;for(unsigned n=0;n<3;++n){auto a=positionKey(t[n].position),b=positionKey(t[(n+1)%3].position);int sign=1;if(b<a){std::swap(a,b);sign=-1;}auto&e=all[{a,b}];++e.first;e.second+=sign;}}unsigned count=0;for(const auto&e:all)if(e.second.first!=2||e.second.second){if(count++<40)printf("edge %d %d (%lld %lld %lld)-(%lld %lld %lld)\n",e.second.first,e.second.second,e.first.first[0],e.first.first[1],e.first.first[2],e.first.second[0],e.first.second[1],e.first.second[2]);}printf("unmatched %u\n",count);}
int main(){auto wood=timberSurface(box(),{{0,.1f}});auto first=splitSurface(wood,bore(),{{0,.1f}});const auto born=renderMesh(first.detached);report("born",born);auto second=bore(.05f);const auto faces=beamPlanes(second.beams[0]);Mesh caps;
for(size_t i=0;i<faces.size();++i){std::vector<storm_ship_hull::Plane>limits;for(size_t j=0;j<faces.size();++j)if(i!=j)limits.push_back(faces[j]);Mesh in,out;solidSectionCaps(born,faces[i],limits,{},true,in,out);float low=1e9,high=-1e9;size_t coplanar=0;double existing=0;for(const auto&o:born)for(const auto&t:o.second){bool same=true;for(const auto&v:t){float d=storm_ship_hull::dot(faces[i].normal,v.position)-faces[i].distance;low=std::min(low,d);high=std::max(high,d);same&=std::abs(d)<1e-6;}if(same){++coplanar;existing+=storm_ship_hull::area(t);}}printf("plane%zu low=%g high=%g coplanar=%zu area=%g\n",i,low,high,coplanar,existing);report("cap",in);appendMesh(caps,in);}
auto standalone=standaloneFragment(born);auto recut=splitSurface(*standalone.surface,second,{});report("kept",renderMesh(recut.kept));edges(renderMesh(recut.kept));report("removed",renderMesh(recut.detached));edges(renderMesh(recut.detached));
for(unsigned role=0;role<4;++role)for(const auto&o:surfaceRole(recut.kept,role))for(const auto&t:o.second){bool same=true;for(const auto&v:t)same&=std::abs(v.position.y+.13f)<1.e-6;if(same){printf("YFACE role%u area %.12g",role,storm_ship_hull::area(t));for(const auto&v:t)printf(" (%0.9g,%0.9g,%0.9g)",v.position.x,v.position.y,v.position.z);puts("");}}
}
